args.sparql:
SELECT ?father ?fatherLabel ?deathDate WHERE {
  dbr:Maria_Anna_Sophia_of_Saxony dbp:father ?father .
  OPTIONAL { ?father dbo:deathDate ?deathDate . }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
}

SELECT ?father ?fatherLabel ?dboDeath ?dbpDeath WHERE {
  dbr:Maria_Anna_Sophia_of_Saxony dbp:father ?father .
  OPTIONAL { ?father dbo:deathDate ?dboDeath . }
  OPTIONAL { ?father dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
}

